'use strict';
const paths={logo:'M5 5h14L5 19h14M12 5v14',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',box:'M4 7l8-4 8 4v10l-8 4-8-4zM4 7l8 4 8-4M12 11v10',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',check:'M20 6L9 17l-5-5',review:'M12 8v4M12 16h.01M10 3L2 18a2 2 0 0 0 2 3h16a2 2 0 0 0 2-3L14 3a2 2 0 0 0-4 0',mail:'M3 5h18v14H3zM3 5l9 7 9-7',chart:'M3 3v18h18M7 16v-4M12 16V7M17 16V4',clock:'M12 8v4l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',plug:'M7 2v6M17 2v6M5 8h14v3a7 7 0 0 1-14 0zM12 18v4',arrow:'M5 12h14M14 7l5 5-5 5',chevron:'M9 5l7 7-7 7',plus:'M12 5v14M5 12h14',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',download:'M12 3v12M7 10l5 5 5-5M4 16v5h16v-5',upload:'M12 16V3M7 8l5-5 5 5M4 16v5h16v-5',play:'M7 4l14 8-14 8z',close:'M6 6l12 12M6 18L18 6',external:'M14 3h7v7M10 14L21 3M10 3H3v18h18v-7',info:'M12 11v6M12 7h.01M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',refresh:'M20 7a9 9 0 1 0 1 8M20 3v5h-5',chat:'M21 11a9 9 0 0 1-9 9c-2 0-4-1-5-1l-5 2 2-5a9 9 0 1 1 17-5',copy:'M8 8h13v13H8zM16 8V3H3v13h5',file:'M14 2H4v20h16V8zM14 2v6h6M8 13h8M8 17h5',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M3 12h18M12 3a18 18 0 0 1 0 18 18 18 0 0 1 0-18',filter:'M3 4h18l-7 8v8l-4-2v-6z',dots:'M5 12h.01M12 12h.01M19 12h.01'};
const I=(name,cls='')=>`<svg viewBox="0 0 24 24" aria-hidden="true" class="${cls}"><path d="${paths[name]||paths.box}"/></svg>`;
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeLink=url=>/^https?:\/\//i.test(url)?esc(url):'#';
const labels={qualified:'符合区间',review:'待复核',skipped:'已跳过',pending:'待采集',error:'采集异常'};
const pages={team:'成员询价总览',contacts:'联系方式',dashboard:'工作台',suppliers:'供应商名录',review:'人工复核',drafts:'询价草稿',insights:'报价洞察',logs:'运行日志',rules:'报价规则',integrations:'能力接入'};
let selectedImportFile=null;
let detailRequest=0,contactEvidenceRequest=0;
const isCloud=()=>state?.deployment==='cloud';
const offerCount=row=>Number.isInteger(row.offer_count)?row.offer_count:row.offers.length;
const offerModels=row=>row.offer_models||row.offers.map(offer=>offer.model);
const importFileLimit=()=>Number.isFinite(state?.limits?.file_bytes)&&state.limits.file_bytes>0?state.limits.file_bytes:5*1024*1024;
async function supplierDetail(id){
 const row=state.suppliers.find(item=>item.id===id);
 if(!row)throw Error('记录不存在');
 if(!row._summary)return row;
 const full=await api('supplier?id='+encodeURIComponent(id));
 if(full.id!==id||full._summary)throw Error('供应商详情加载失败，请重试');
 const index=state.suppliers.findIndex(item=>item.id===id);
 if(index>=0)state.suppliers[index]=full;
 return full;
}
let state,mode=new URLSearchParams(location.search).get('mode')||localStorage.getItem('scout-mode')||'demo',page=new URLSearchParams(location.search).get('page')||'dashboard',filter='all',search='',pageNo=1,drawerId=null,modalType=null,lastBusy=false,refreshing=false;
if(!['real','demo'].includes(mode))mode='demo';if(!pages[page])page='dashboard';
const rows=()=>state.suppliers.filter(r=>r.mode===mode);
const counts=()=>rows().reduce((a,r)=>(a[r.status]=(a[r.status]||0)+1,a),{});
const badge=s=>`<span class="badge ${esc(s)}">${labels[s]||esc(s)}</span>`;
const time=s=>s?new Date(s).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}):'尚未采集';
const modelName=s=>state.rules.find(r=>r.model===s)?.label||s||'尚未识别';
const ratio=v=>Number.isFinite(v)?`${Number((v*10).toFixed(2))}<small>折</small>`:'<span style="color:#bbb">—</span>';
const initials=name=>/^[A-Za-z]/.test(name)?name.split(/\s+/).map(s=>s[0]).join('').slice(0,2).toUpperCase():name.slice(0,1);
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4000)}
async function api(path,data){const options=data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)};const res=await fetch('/api/'+path,options);if(res.status===401){const next=location.pathname+location.search;location.assign('/login?'+new URLSearchParams({next:next.startsWith('/')&&!next.startsWith('//')?next:'/'}));throw Error('登录已过期，请重新登录')}const result=await res.json();if(!res.ok)throw Error(result.error||'请求失败');return result}
async function load(render=true){if(refreshing)return;refreshing=true;try{state=await api('state');if(render)renderApp()}catch(e){if(!state)$('#main').innerHTML=`<div class="empty">无法连接工作区服务：${esc(e.message)}<br>${['localhost','127.0.0.1'].includes(location.hostname)?'请运行项目中的「启动.command」后刷新页面。':'请检查网络连接后刷新页面。'}</div>`;else toast(e.message)}finally{refreshing=false}}
function renderNav(){const footer=$('footer');if(footer)footer.innerHTML=`<span>寻源 Supplier Scout <b>${isCloud()?'CLOUD':'LOCAL'} · v0.1</b></span><span>${isCloud()?'数据保存在云端':'数据保存在本机'} · 无外部消息发送</span>`;const c=counts();const pendingTasks=rows().filter(isManualTask).length;$('#sidebar').innerHTML=`<div class="brand"><div class="brand-logo">${I('logo')}</div><div><strong>寻源</strong><small>SUPPLIER SCOUT</small></div></div><div class="space-card"><div class="space-avatar">${I('box')}</div><div><strong>模型采购工作区</strong><small>Personal workspace</small></div></div><div class="nav-label">WORKSPACE</div>${[['dashboard','grid'],['contacts','chat'],['suppliers','users'],['review','review'],['drafts','mail'],['insights','chart'],['logs','clock']].map(([key,icon])=>`<button class="nav ${page===key?'active':''}" data-nav="${key}" title="${pages[key]}">${I(icon)}<span>${pages[key]}</span>${key==='review'&&pendingTasks?`<b class="count">${pendingTasks}</b>`:''}</button>`).join('')}${state.is_admin?`<button class="nav ${page==='team'?'active':''}" data-nav="team">${I('users')}<span>成员询价总览</span></button>`:''}<div class="nav-label nav-sep">MANAGE</div>${[['rules','settings'],['integrations','plug']].map(([key,icon])=>`<button class="nav ${page===key?'active':''}" data-nav="${key}" title="${pages[key]}">${I(icon)}<span>${pages[key]}</span></button>`).join('')}<div class="sidebar-bottom"><div class="local-card"><strong><i class="dot"></i> ${isCloud()?'云端工作区已连接':'本地工作区已连接'}</strong><p>${isCloud()?'数据安全保存在云端<br>关闭电脑后仍可继续采集':'你的数据保存在这台电脑<br>轻量运行，随时继续'}</p></div><div class="profile"><div class="avatar">我</div><div><strong>${esc(state.username||'采购团队')}</strong><small>${state.is_admin?'超级管理员':isCloud()?'成员工作区':'本地体验版'}</small></div></div></div>`;
$('#topbar').innerHTML=`<div class="breadcrumbs">${I('grid')}<span>模型采购工作区</span><span>/</span><strong>${pages[page]}</strong></div><div class="top-actions">${state.job.running?stopButton():''}<div class="mode-switch" aria-label="切换数据工作区"><button data-mode="demo" class="${mode==='demo'?'selected':''}">示例体验</button><button data-mode="real" class="${mode==='real'?'selected':''}">真实采集</button></div><div class="local-tag"><i class="dot"></i> ${isCloud()?'云端运行':'本地运行'}</div>${state.username?'<span class="form-note">当前账号：'+esc(state.username)+'</span>':''}${state.auth_enabled?'<button class="btn small" data-action="logout">退出登录</button>':''}<button class="top-info" data-action="about" title="版本与能力说明">${I('info')}</button></div>`}
function notice(){return mode==='demo'?`<div class="notice">${I('info')}<span><strong>正在查看示例工作区</strong> · 以下供应商、报价与联系方式均为虚构数据，演示回放不会访问或联系真实供应商。</span><button data-mode="real">切换真实采集 ${I('arrow')}</button></div>`:`<div class="notice">${I('globe')}<span><strong>真实采集工作区</strong> · 选择全量或仅联系方式，配置 API 后由模型驱动 Moli 浏览器采集。运行过程、来源证据和受阻原因均会保存。</span></div>`}
function heading(title,sub,buttons='',eyebrow='SOURCING WORKSPACE'){return `<div class="page-title"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div><div class="page-actions">${buttons}</div></div>`}
function stopButton(){if(state.username&&state.job.requested_by&&state.username!==state.job.requested_by)return `<span class="form-note">${esc(state.job.requested_by)} 正在采集</span>`;return `<button class="btn danger" data-action="stop" ${state.job.stopping&&!(state.job.heartbeat_age>60)?'disabled':''}>${I('close')}${state.job.stopping&&!(state.job.heartbeat_age>60)?'正在停止…':'停止采集'}</button>`}
function jobHint(){const j=state.job;const text=j.status==='queued'&&j.waiting_seconds>120?'等待云端浏览器启动…已等待 '+j.waiting_seconds+' 秒':['running','stopping'].includes(j.status)&&j.heartbeat_age>60?'后台心跳中断（'+j.heartbeat_age+' 秒无响应），可点击停止后重新开始':'';return text?`<span class="form-note" style="display:block;margin-top:7px;color:#b4553f">${esc(text)}</span>`:''}
function runButton(){const busy=state.job.running;return `${busy?stopButton():''}<button class="btn primary" data-action="run" ${busy?'disabled':''}>${I(busy?'refresh':'play',busy?'spin':'')}${busy?'批次运行中':mode==='demo'?'回放示例流程':'开始采集…'}</button>`}
function importButton(){return `<button class="btn" data-action="import">${I('plus')}添加地址 / 导入表格</button>`}
function metrics(){const c=counts(),total=rows().length;return `<div class="metrics">${[
['供应商总数',total,'users',`<span>${mode==='demo'?'12 家示例 · ':''}名单与线索统一管理</span>`],['符合目标区间',c.qualified||0,'check',`<span class="good">${total?Math.round((c.qualified||0)/total*100):0}%</span><span>占当前供应商总数</span>`],['等待人工复核',c.review||0,'review',`<span class="warn">${c.review?'需要你判断':'暂无待办'}</span><span>· 异常低价 / 信息待补充</span>`],['联系方式覆盖',rows().filter(r=>Object.values(r.contacts).some(v=>v.length)).length,'chat',`<span>邮箱、微信等公开联络线索</span>`]].map(([label,val,icon,meta])=>`<div class="metric"><div class="metric-heading">${label}<span class="metric-icon">${I(icon)}</span></div><div class="metric-value">${val}<small>家</small></div><div class="metric-meta">${meta}</div></div>`).join('')}</div>`}
function pipeline(){const busy=state.job.running&&state.job.mode===mode;return `<div class="panel pipeline"><div class="pipeline-top"><div class="panel-title">${I('refresh',busy?'spin':'')}寻源工作流</div><span class="chip">${busy?'运行中':mode==='demo'?'示例流程 · 可回放':'Moli 浏览器 Agent · 最多 12 步 / 站'}</span></div><div class="flow">${[['upload','导入名单','网址 / Excel'],['globe','采集网页','保留来源与证据'],['filter','折扣筛选','按模型区间判断'],['chat','提取联系','缺失线索待补查'],['mail','生成询价','保存草稿，人工发送'],['chart','跟踪报价','历史留存 / CSV 导出']].map(([icon,label,desc],i)=>`${i?'<div class="flow-line"></div>':''}<div class="flow-step"><div class="flow-icon">${I(icon)}</div><div><strong>${label}</strong><small>${desc}</small></div></div>`).join('')}</div>${busy?`<div class="job-progress">${state.job.stopping?'正在停止':state.job.scope==='contacts'?'仅采集联系方式':'全量采集'} ${state.job.requested_by?'发起人 '+esc(state.job.requested_by)+' · ':''}${esc(state.job.current)} · ${state.job.done} / ${state.job.total}<br><span style="display:block;margin-top:7px;color:#9690a7;overflow-wrap:anywhere">${esc(state.job.stage||'')}</span>${jobHint()}<div class="progress-track"><i style="width:${100*state.job.done/state.job.total}%"></i></div></div>`:state.job.mode===mode&&state.job.status==='failed'?`<div class="job-progress">模型服务失败，已停止批次：${esc(state.job.error||'请检查能力接入设置')}</div>`:state.job.mode===mode&&state.job.status==='stopped'?`<div class="job-progress">已停止 · 已处理 ${state.job.done} / ${state.job.total} 家，结果已保留。再次开始仅处理剩余未采集记录。</div>`:''}<div class="stat-note">采集方式：模型逐轮观察 Moli 页面，自主选择公告、联系入口和二维码。仅联系方式模式保留原有报价；单站最多 12 步、10 分钟，可随时停止。</div></div>`}
function contactIcons(r){return `<div class="contact-icons">${Object.entries(r.contacts).filter(([,v])=>v.length).slice(0,3).map(([k,v])=>`<span title="${esc(k+': '+v.join(', '))}">${k==='email'?I('mail'):k==='wechat'?I('chat'):k==='phone'?'电':k==='qq'?'Q':I('globe')}</span>`).join('')||'<span title="待补查">—</span>'}</div>`}
function tableRows(data){return data.map(r=>{const names=[...new Set(offerModels(r).map(modelName))];return `<tr><td><button class="supplier-cell" data-detail="${r.id}" style="text-align:left;padding:0"><span class="avatar c${r.id%5}">${esc(initials(r.name))}</span><span><strong>${esc(r.name)}</strong><small>${esc(new URL(r.url).hostname)}</small></span></button></td><td class="model-column">${names.slice(0,2).map(name=>`<span class="model-label">${esc(name)}</span>`).join('')||'<span class="contact-empty">尚无目标模型报价</span>'}${names.length>2?`<small>另 ${names.length-2} 类模型</small>`:''}</td><td>${quoteSummary(r)}</td><td>${stageBadges(r)}</td><td>${contactColumn(r)}</td><td><button class="icon-btn" data-detail="${r.id}" title="查看 ${esc(r.name)} 的报价与复核">${I('arrow')}</button></td></tr>`}).join('')}
function filteredRows(){let data=rows();if(page==='review'&&!filter.startsWith('todo_'))data=data.filter(isManualTask);if(filter.startsWith('todo_'))data=data.filter(r=>matchesTask(r,filter));else if(filter!=='all')data=data.filter(r=>r.status===filter);if(search)data=data.filter(r=>(r.name+' '+r.url+' '+offerModels(r).map(model=>modelName(model)+' '+model).join(' ')).toLowerCase().includes(search.toLowerCase()));return data}
function tableBody(dashboard){const all=filteredRows(),size=dashboard?6:12,max=Math.max(1,Math.ceil(all.length/size));pageNo=Math.min(pageNo,max);const data=all.slice((pageNo-1)*size,pageNo*size);return `${data.length?`<div class="table-scroll"><table><thead><tr><th>编号 / 供应商</th><th>模型</th><th>报价 / 折扣</th><th>处理阶段 / 下一步</th><th class="contact-col-head">联系方式</th><th></th></tr></thead><tbody>${tableRows(data)}</tbody></table></div>`:`<div class="empty">${I('search')}${search?'没有找到匹配的供应商':page==='review'?'暂无待复核供应商':mode==='real'?'导入第一批供应商，开始真实采集':'当前筛选下没有供应商'}${mode==='real'&&!rows().length?'<br><button class="btn small" data-action="import">导入供应商</button>':''}</div>`}<div class="table-footer"><span>${all.length?`显示 ${(pageNo-1)*size+1}–${Math.min(pageNo*size,all.length)} 条，共 ${all.length} 家`:'暂无记录'}</span>${dashboard?`<button class="text-btn" data-nav="suppliers">查看全部 ${I('arrow')}</button>`:`<div class="pagination"><button data-action="prev" ${pageNo<=1?'disabled':''}>‹</button><span>${pageNo} / ${max}</span><button data-action="next" ${pageNo>=max?'disabled':''}>›</button></div>`}</div>`}
function table(dashboard=false){return `<section class="panel table-panel"><div class="panel-head"><div class="panel-title">${dashboard?'供应商速览':page==='review'?'待处理线索':'全部供应商'}<span class="chip">${page==='review'?filteredRows().length:rows().length}</span></div><a class="text-btn" href="/api/export?mode=${mode}">${I('download')}导出 CSV</a></div><div class="table-tools"><div class="search">${I('search')}<input id="search" aria-label="搜索供应商" placeholder="搜索供应商、网址或模型…" value="${esc(search)}"></div>${page==='review'?`<div class="filters">${taskFilters()}</div>`:`<div class="filters">${taskFilters()}<select id="extra-filter" aria-label="其他筛选状态" class="filter" style="border:1px solid #edeef4;background:#fff"><option value="">更多</option><option value="skipped" ${filter==='skipped'?'selected':''}>已跳过</option><option value="error" ${filter==='error'?'selected':''}>采集异常</option></select></div>`}</div><div id="table-body">${tableBody(dashboard)}</div></section>`}
function donutPanel(){const c=counts(),total=rows().length,parts=[['qualified','符合区间','#8a7be1'],['review','待复核','#e9c87c'],['skipped','已跳过','#b8c0d3'],['pending','待采集 / 异常','#eeedf5']];let pos=0;const gradient=parts.map(([k,,color])=>{const v=(c[k]||0)+(k==='pending'?(c.error||0):0),from=pos;pos+=total?v/total*100:0;return `${color} ${from}% ${pos}%`}).join(',');return `<section class="panel"><div class="panel-head"><div><div class="panel-title">筛选概况</div><div class="panel-sub">当前工作区 · 最新结果</div></div>${I('chart')}</div><div class="donut-layout"><div class="donut" style="background:${total?'conic-gradient('+gradient+')':'#eeedf5'}"><div class="donut-center"><strong>${total?Math.round((c.qualified||0)/total*100):0}<span style="font-size:13px">%</span></strong><small>符合区间占比</small></div></div><div class="legend">${parts.map(([k,t,color])=>`<div class="legend-row"><i style="--color:${color}"></i><span>${t}</span><strong>${(c[k]||0)+(k==='pending'?(c.error||0):0)}</strong></div>`).join('')}</div></div></section>`}
function opportunities(){return `<section class="panel"><div class="panel-head"><div class="panel-title">模型采购目标</div><button class="text-btn" data-nav="rules">管理 ${I('chevron')}</button></div><div class="model-list">${state.rules.map(rule=>{const n=rows().filter(r=>r.offers.some(o=>o.model===rule.model&&o.status==='qualified')).length;return `<div class="model-row"><div class="model-row-top"><span>${esc(rule.label||rule.model)}</span><strong>${ruleThresholdText(rule)}</strong></div><div class="thin-bar"><i style="width:${Math.min(100,n/Math.max(rows().length,1)*180)}%"></i></div><small>${n} 家报价落在区间内 · 未计人工状态覆盖</small></div>`}).join('')}</div><div class="stat-note">范围来自 A 部分报价规则。分组倍率、充值优惠和官方折扣分别记录，不混为同一种价格。</div></section>`}
function activities(limit=3){const events=state.events.filter(e=>e.mode===mode).slice(0,limit);return events.length?events.map(e=>`<div class="activity-row"><span class="activity-icon">${I(e.message.includes('失败')?'review':e.message.includes('导入')?'upload':'check')}</span><div><p>${esc(e.message)}</p><time>${time(e.created_at)}</time></div>${e.supplier_id?`<button class="icon-btn" style="margin-left:auto" data-detail="${e.supplier_id}" title="查看相关供应商">${I('chevron')}</button>`:''}</div>`).join(''):'<div class="empty" style="padding:25px">尚无运行记录</div>'}
function renderLegacyApp(){if(!state)return;renderNav();const exportBtn=`<a class="btn" href="/api/export?mode=${mode}">${I('download')}导出结果</a>`;let html='';
if(page==='dashboard')html=heading('供应商工作台','从公开线索到采购机会，让每一次询价都有依据。',importButton()+runButton())+notice()+metrics()+pipeline()+`<div class="dashboard-grid">${table(true)}<div class="side-stack">${donutPanel()}${opportunities()}</div></div><div class="bottom-grid"><section class="panel"><div class="panel-head"><div class="panel-title">${I('clock')}最近动态</div><button class="text-btn" data-nav="logs">全部日志 ${I('arrow')}</button></div><div class="activity">${activities(2)}</div></section><div class="hint-card"><strong>先找到合适的，再开始对话。</strong><p>价格接近区间、低得异常或缺少联系方式的供应商，会进入人工复核。每一条线索保留原文，方便你做最终判断。</p><button class="btn small" data-nav="review">查看待办 ${I('arrow')}</button></div></div>`;
else if(page==='suppliers'||page==='review')html=heading(pages[page],page==='review'?'先看依据，再做决定。复核记录会保留在运行日志中。':'把分散的供应商线索，整理成可跟进的采购名单。',page==='review'?exportBtn:importButton()+runButton())+notice()+(page==='suppliers'?pipeline():'')+table();
else if(page==='insights')html=heading('报价洞察','按模型查看当前报价分布；历史采集记录独立留存。',exportBtn,'PRICING INTELLIGENCE')+notice()+metrics()+insights();
else if(page==='rules')html=heading('筛选规则','用明确的区间定义采购目标，让每次判断保持一致。',`<button class="btn primary" data-action="save-rules">${I('check')}保存规则</button>`,'DECISION RULES')+`<div class="notice">${I('info')}规则对两个工作区生效；已有记录保留原判断，重新运行分析后应用新规则。基准价格为示例，并非实时官方价格。</div><div class="section-grid"><section class="panel"><div class="panel-head"><div class="panel-title">规则配置 <span class="chip">JSON</span></div><button class="text-btn" data-action="format-rules">格式化</button></div><div class="settings-content"><textarea class="rule-editor" id="rule-editor" aria-label="折扣规则 JSON" spellcheck="false">${esc(JSON.stringify(state.rules,null,2))}</textarea><div class="form-error" id="rules-error"></div></div></section><section class="panel"><div class="panel-head"><div class="panel-title">如何判断</div></div><div class="settings-content rule-explain"><div class="rule-chip"><strong>0.35 = 3.5 折</strong><small>比例越低，折扣越大；这里的“3 折”表示原价的 30%。</small></div><p><strong>符合区间</strong><br>min_ratio ≤ 报价比例 ≤ max_ratio</p><p><strong>需要复核</strong><br>低于下限的异常低价，或高于上限但在 review_margin 容差内；缺少明确报价、联系方式或模型规则。</p><p><strong>跳过</strong><br>比例高于上限与复核容差之和。</p><p>公开页面当前只抽取明确写出的模型折扣；不同币种、单位和版本不会自动换算。价格基准字段供后续结构化报价接入使用。</p></div></section></div>`;
else if(page==='logs')html=heading('运行日志','每次采集、判断和人工处理，都留下可追溯的记录。',`<button class="btn" data-action="refresh">${I('refresh')}刷新</button>`,'ACTIVITY LOG')+notice()+`<section class="panel"><div class="panel-head"><div class="panel-title">工作区动态</div><span class="chip">最近 300 条 / 两个工作区</span></div><div class="activity events-list">${activities(300)}</div></section>`;
else if(page==='drafts')html=renderDrafts();
else if(page==='integrations')html=heading('能力接入','本地流程已能运行，外部服务按你们的账号与环境接入。','','CONNECTIONS')+`<div class="integration-grid">${[['mail','邮箱','未接入','当前支持生成、编辑和下载 .eml 草稿；回复可手动粘贴分析。自动收发需配置邮箱服务及授权。','查看询价草稿','drafts'],['plug','飞书','未接入','当前支持 CSV 导出后导入飞书表格。自动写表、提醒和日报推送需配置应用权限与目标表格。','导出当前工作区','export'],['filter','AI 语义识别','未接入','当前使用确定性规则识别明确折扣与文本联系方式。复杂价格表、图片二维码及动态网页需扩展采集能力。','查看筛选规则','rules']].map(([icon,title,status,desc,cta,target])=>`<section class="panel integration-card"><div class="integration-icon">${I(icon)}</div><h3>${title}</h3><span class="badge pending">${status}</span><p>${desc}</p>${target==='export'?`<a class="btn small" href="/api/export?mode=${mode}">${I('download')}${cta}</a>`:`<button class="btn small" data-nav="${target}">${cta} ${I('arrow')}</button>`}</section>`).join('')}</div><div class="panel roadmap"><strong style="color:#747b8e">当前运行边界</strong><br>网站采集遵循 robots.txt，最多读取同站 3 页。登录页、验证码、图片二维码暂不支持；动态网页尝试独立浏览器加载，失败会标记供人工处理。<br>统计图展示当前报价，不生成虚构历史趋势。每日自动调度和外部推送尚未启用；当前通过按钮运行、停止和导出。</div>`;
$('#main').innerHTML=html;lastBusy=state.job.running;}
function insights(){const offers=rows().flatMap(r=>r.offers.filter(o=>Number.isFinite(o.ratio)).map(o=>({...o,supplier:r.name}))),bins=[['低于 3 折',0,.3],['3–4 折',.3,.4],['4–5 折',.4,.5],['5–6 折',.5,.6],['6 折及以上',.6,Infinity]];const counts=bins.map(([,lo,hi])=>offers.filter(o=>o.ratio>=lo&&o.ratio<hi).length),max=Math.max(1,...counts);return `<div class="section-grid"><section class="panel"><div class="panel-head"><div><div class="panel-title">公开折扣分布</div><div class="panel-sub">${offers.length} 条明确折扣 · 同一家不同模型分别计数</div></div>${I('chart')}</div><div class="big-chart">${bins.map(([label],i)=>`<div class="bar-row"><span>${label}</span><div class="bar-track"><i style="width:${counts[i]/max*100}%"></i></div><strong>${counts[i]} 条 / ${offers.length?Math.round(counts[i]/offers.length*100):0}%</strong></div>`).join('')}</div><div class="stat-note">区间左闭右开，例如 4 折计入“4–5 折”；公开折扣尚未验证模型质量、缓存计价或优惠限制。</div></section>${opportunities()}</div><section class="panel" style="margin-top:20px"><div class="panel-head"><div class="panel-title">报价历史</div><span class="chip">最近 500 条 / 两个工作区</span></div><div class="activity">${state.history.filter(h=>h.mode===mode).slice(0,20).map(h=>`<div class="history-item"><strong>${esc(state.suppliers.find(s=>s.id===h.supplier_id)?.name||'供应商')}</strong> · ${h.offers.map(o=>`${esc(o.model_name||modelName(o.model))} ${Number.isFinite(o.ratio)?Number((o.ratio*10).toFixed(2))+'折':'待核对'}`).join(' / ')}<span style="float:right">${time(h.created_at)}</span></div>`).join('')||'<div class="empty">采集到明确报价后，这里会保留每次记录。</div>'}</div></section>`}
function renderDrafts(){const drafts=state.drafts.filter(d=>rows().some(r=>r.id===d.supplier_id));const eligible=rows().filter(r=>r.contacts.email?.length&&r.status==='qualified');return heading('询价草稿','先整理问题，再发起询价。草稿不会自动发送。','','OUTREACH')+notice()+`<div class="draft-count">已保存 ${drafts.length} 份草稿 · ${eligible.length} 家符合区间的供应商可询价</div>${drafts.map(d=>{const r=rows().find(r=>r.id===d.supplier_id);return `<article class="panel draft-card"><span class="avatar c${r.id%5}">${esc(initials(r.name))}</span><div><h3>${esc(d.subject)}</h3><p>${esc(r.name)} · ${esc(r.contacts.email?.[0])} · 保存于 ${time(d.created_at)} · 未发送</p></div><button class="btn small" data-draft="${r.id}">编辑草稿 ${I('arrow')}</button></article>`}).join('')||'<div class="panel empty">'+I('mail')+'尚未保存询价草稿<br>从下方供应商生成第一封询价邮件。</div>'}<section class="panel" style="margin-top:22px"><div class="panel-head"><div class="panel-title">可询价供应商</div><span class="chip">有邮箱 · 符合区间</span></div>${eligible.map(r=>`<div class="draft-card" style="border-top:1px solid var(--line);margin:0;padding:16px 20px"><span class="avatar c${r.id%5}">${esc(initials(r.name))}</span><div><h3>${esc(r.name)}</h3><p>${esc(r.contacts.email[0])}</p></div><button class="btn small" data-draft="${r.id}">${I('plus')}生成草稿</button></div>`).join('')||'<div class="empty">暂无符合条件且有邮箱的供应商</div>'}</section>`}
function openModal(html,type){if(type!=='contact-evidence')contactEvidenceRequest++;modalType=type;$('#modal').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function modalHead(title,sub=''){return `<div class="dialog-head"><div><h2>${title}</h2>${sub?`<small>${sub}</small>`:''}</div><button class="icon-btn" data-action="close-modal" title="关闭">${I('close')}</button></div>`}
function openImport(){selectedImportFile=null;openModal(modalHead('添加地址 / 导入表格','不需要供应商名称；已有编号会保留，没有编号就自动生成')+`<div class="dialog-body"><div class="dropzone">${I('upload')}<p>直接选择 Excel 表格，编号和地址两列就够了</p><input type="file" id="import-file" accept=".xlsx,.csv,.tsv,.json,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" aria-label="选择 Excel 或名单文件"><div class="form-note" id="import-file-note" style="margin-top:10px">支持 Excel（.xlsx），也支持从表格复制粘贴。最多 5000 条，文件不超过 ${Number((importFileLimit()/1024/1024).toFixed(2))}MB，无需改表头。</div></div><label class="field">或者直接粘贴网址<textarea id="import-text" rows="7" placeholder="api.holysheep.ai&#10;https://example.com/pricing&#10;&#10;一个网址就能导入，也可以粘贴整列地址或编号＋地址两列"></textarea><small>复制你能打开的网页地址即可；缺少的网址前缀会自动补齐，不用填写供应商名称。</small></label><div class="form-error" id="import-error"></div></div><div class="dialog-footer"><button class="btn" data-action="close-modal">取消</button><button class="btn primary" id="import-submit" data-action="confirm-import">${I('upload')}导入</button></div>`,'import')}
function readFileBase64(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('文件读取失败，请重新选择'));reader.readAsDataURL(file)})}
async function previewImportFile(file){if(!file)return;selectedImportFile=null;$('#import-text').value='';if(file.size>importFileLimit()){$('#import-error').textContent=`文件请控制在 ${Number((importFileLimit()/1024/1024).toFixed(2))}MB 以内`;$('#import-file-note').textContent='文件尚未导入';return}const submit=$('#import-submit');submit.disabled=true;selectedImportFile=null;$('#import-error').textContent='';$('#import-file-note').textContent='正在读取表格…';try{const payload={filename:file.name,file_base64:await readFileBase64(file)};const result=await api('import-preview',payload);selectedImportFile=payload;$('#import-text').value=result.rows.map(row=>{const number=row.number??row.source_row??row.name??'';return (number?number+'\t':'')+row.url}).join('\n');$('#import-file-note').textContent=`已识别 ${result.valid_count} 条地址，编号自动保留。${result.rejected.length?'另有 '+result.rejected.length+' 行无法识别，导入时会单独提示。':'点击“导入”即可。'}`;if(!result.valid_count)$('#import-error').textContent='没有找到可用地址，请检查表格，或直接在下方粘贴网址'}catch(error){$('#import-file-note').textContent='文件尚未导入';$('#import-error').textContent=error.message}finally{submit.disabled=false}}
async function openDetail(id){
 const request=++detailRequest;drawerId=id;
 const preview=state.suppliers.find(row=>row.id===id);
 if(!preview)return toast('记录不存在');
 if(preview._summary){$('#drawer').innerHTML=modalHead(esc(preview.name),'正在加载完整报价与来源…').replace('close-modal','close-drawer')+'<div class="drawer-section" role="status">正在加载供应商详情…</div>';if(!$('#drawer').open)$('#drawer').showModal();}
 try{const r=await supplierDetail(id);if(request!==detailRequest||drawerId!==id)return;renderDetail(r);}catch(error){if(request!==detailRequest)return;if($('#drawer').open)$('#drawer').innerHTML=modalHead('详情加载失败').replace('close-modal','close-drawer')+`<div class="drawer-section">${esc(error.message)}<p>关闭后重新打开可重试。</p></div>`;else toast(error.message)}
}
function renderDetail(r){$('#drawer').innerHTML=modalHead(esc(/^\d+$/.test(r.name)?'供应商 '+r.name:r.name),`${esc(new URL(r.url).hostname)} · ${r.mode==='demo'?'虚构演示供应商':'真实采集记录'}` ).replace('close-modal','close-drawer')+`<div class="drawer-section"><div class="detail-status">${stageBadges(r,true)}<button class="btn small" data-rerun="${r.id}" ${state.job.running?'disabled':''}>${I('refresh')}重新分析</button></div><div class="detail-reason">按模型展开报价，查看单价、分组和原始来源。</div><a class="source-link" href="${safeLink(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.url)} ${I('external')}</a><p>最近采集：${time(r.checked_at)}</p>${r.warnings.length?`<details class="quote-warning"><summary>采集说明与待核实事项 · ${r.warnings.length} 项</summary>${r.warnings.map(w=>`<div class="warning">${esc(w)}</div>`).join('')}</details>`:''}</div><section class="drawer-section"><h3>供应商报价 <span class="chip">${r.offers.length} 条</span></h3>${quoteCards(r)}</section><details class="quote-secondary"><summary>人工复核</summary><section class="drawer-section"><h3>人工复核</h3><label class="field">处理结果<select id="review-status"><option value="qualified" ${r.status==='qualified'?'selected':''}>符合区间 · 继续跟进</option><option value="review" ${!['qualified','skipped'].includes(r.status)?'selected':''}>待复核 · 继续补查</option><option value="skipped" ${r.status==='skipped'?'selected':''}>跳过 · 暂不跟进</option></select></label><label class="field">复核依据<textarea id="review-note" rows="3" placeholder="例如：已核对模型版本与价格，保留跟进">${esc(r.notes)}</textarea></label><button class="btn primary small" data-review="${r.id}">${I('check')}保存复核结果</button><div class="form-error" id="review-error"></div></section></details><details class="quote-secondary"><summary>粘贴询价回复</summary><section class="drawer-section"><h3>粘贴询价回复</h3><label class="field">收到邮件或聊天回复后，粘贴正文<textarea id="reply-text" rows="4" placeholder="例如：DeepSeek-V3 长期 3.5折&#10;邮箱 sales@…"></textarea><small>此操作按当前供应商关联，不会读取邮箱。仅明确的单模型折扣自动提取；旧报价保留在历史中。</small></label><button class="btn small" data-reply="${r.id}">${I('filter')}分析并记录回复</button><div class="form-error" id="reply-error"></div></section></details><details class="quote-secondary"><summary>来源摘录</summary><section class="drawer-section"><h3>来源摘录</h3>${r.sources.map(s=>`<details style="margin:10px 0"><summary class="form-note" style="cursor:pointer;overflow-wrap:anywhere">${esc(s.url)} · ${esc(s.method||'普通网页')} · ${s.text_length??s.excerpt.length} 字</summary><div class="evidence">${esc(s.excerpt)}</div></details>`).join('')||'<p>首次采集后显示来源。</p>'}</section></details><details class="quote-secondary"><summary>报价历史</summary><section class="drawer-section"><h3>报价历史</h3>${state.history.filter(h=>h.supplier_id===r.id).slice(0,10).map(h=>`<div class="history-item">${time(h.created_at)} · ${h.offers.map(o=>esc(modelName(o.model))+' '+(Number.isFinite(o.ratio)?Number((o.ratio*10).toFixed(2))+'折':'待核对')).join(' / ')}</div>`).join('')||'<p>暂无历史报价</p>'}</section></details>`;if(!$('#drawer').open)$('#drawer').showModal()}
function openDraft(id){const r=state.suppliers.find(r=>r.id===id);if(!r?.contacts.email?.length)return toast('该供应商尚无邮箱');const saved=state.drafts.find(d=>d.supplier_id===id);const models=[...new Set(offerModels(r))].join('、')||'大模型';const subject=saved?.subject||`【询价 #S${id}】${models} API 批量采购合作`;const body=saved?.body||`您好，${r.name}团队：\n\n我们正在评估 ${models} 的 API 采购方案，希望了解以下信息：\n\n1. 完整模型名称与版本、输入/输出/缓存价格、币种及计价单位；\n2. 阶梯折扣、最低采购量、有效期及其他适用条件；\n3. 服务来源、并发与限流、稳定性保障；\n4. 结算方式、发票及售后联系方式。\n\n烦请提供正式报价及价格页链接。回复时请保留主题中的 #S${id}，便于关联询价。\n\n谢谢！\n[请填写姓名 / 公司 / 联系方式]`;if($('#drawer').open)$('#drawer').close();openModal(modalHead('询价邮件草稿',r.mode==='demo'?'演示草稿 · 虚构收件人，请勿实际发送':'保存和下载草稿后，可在你自己的邮件客户端发送')+`<div class="dialog-body"><label class="field">收件人<input value="${esc(r.contacts.email[0])}" readonly></label><label class="field">主题<input id="draft-subject" value="${esc(subject)}" maxlength="300"></label><label class="field">正文<textarea id="draft-body" rows="12">${esc(body)}</textarea></label><div class="form-note">当前未接入邮箱，不会发送邮件；请补充署名并核对收件人。下载的 .eml 可在邮件客户端打开。</div><div class="form-error" id="draft-error"></div></div><div class="dialog-footer"><button class="btn" data-save-draft="${id}">保存草稿</button><button class="btn primary" data-download-draft="${id}">${I('download')}保存并下载 .eml</button></div>`,'draft')}
async function saveDraft(id,download){try{await api('drafts',{id,subject:$('#draft-subject').value,body:$('#draft-body').value});await load();if(download){const a=document.createElement('a');a.href='/api/draft?id='+id;a.download='inquiry-'+id+'.eml';document.body.append(a);a.click();a.remove()}toast(download?'草稿已保存并下载，邮件未发送':'草稿已保存，邮件未发送')}catch(e){$('#draft-error').textContent=e.message}}
function navigate(next){detailRequest++;contactEvidenceRequest++;drawerId=null;page=next;filter='all';search='';pageNo=1;if($('#drawer').open)$('#drawer').close();if($('#modal').open)$('#modal').close();renderApp();window.scrollTo({top:0,behavior:'smooth'})}
document.addEventListener('click',async e=>{const el=e.target.closest('button,a');if(!el)return;try{
if(el.dataset.nav)return navigate(el.dataset.nav);
if(el.dataset.mode){mode=el.dataset.mode;localStorage.setItem('scout-mode',mode);filter='all';search='';pageNo=1;renderApp();return}
if(el.dataset.filter){filter=el.dataset.filter;pageNo=1;renderApp();return}
if(el.dataset.detail)return openDetail(Number(el.dataset.detail));
if(el.dataset.draft)return openDraft(Number(el.dataset.draft));
if(el.dataset.copy){await navigator.clipboard.writeText(el.dataset.copy);return toast('已复制联系方式')}
if(el.dataset.saveDraft)return saveDraft(Number(el.dataset.saveDraft),false);
if(el.dataset.downloadDraft)return saveDraft(Number(el.dataset.downloadDraft),true);
if(el.dataset.review){try{await api('review',{id:Number(el.dataset.review),status:$('#review-status').value,note:$('#review-note').value});await load();openDetail(Number(el.dataset.review));toast('复核结果已保存，依据已记录')}catch(err){$('#review-error').textContent=err.message}return}
if(el.dataset.reply){el.disabled=true;try{const result=await api('reply',{id:Number(el.dataset.reply),text:$('#reply-text').value});await load();openDetail(Number(el.dataset.reply));toast(result.offers?`识别 ${result.offers} 条折扣，已保留回复原文`:'回复已保存；没有明确折扣，已标记待复核')}catch(err){$('#reply-error').textContent=err.message}finally{el.disabled=false}return}
if(el.dataset.rerun){const id=Number(el.dataset.rerun);$('#drawer').close();return openRun([id])}
switch(el.dataset.action){
case 'logout':el.disabled=true;try{await api('auth/logout',{});location.assign('/login')}catch(error){el.disabled=false;toast(error.message)}return;
case 'import':return openImport();case 'close-modal':contactEvidenceRequest++;return $('#modal').close();case 'close-drawer':detailRequest++;drawerId=null;return $('#drawer').close();
case 'stop':await api('stop',{});await load();return toast('停止请求已提交，保留已完成结果');
case 'run':return openRun();
case 'refresh':await load();return toast('数据已刷新');
case 'prev':pageNo--;renderApp();return;case 'next':pageNo++;renderApp();return;
case 'confirm-import':el.disabled=true;try{const payload=selectedImportFile||{text:$('#import-text').value};const result=await api('import',payload);mode='real';localStorage.setItem('scout-mode',mode);$('#modal').close();page='suppliers';filter='all';search='';pageNo=1;await load();toast(`已导入 ${result.added} 条地址，跳过 ${result.duplicates} 条重复记录${result.rejected.length?'；另有 '+result.rejected.length+' 行未识别':''}`);if(result.rejected.length)openModal(modalHead('可用地址已导入',`${result.added} 条已导入 · ${result.duplicates} 条重复 · ${result.rejected.length} 行未识别`)+`<div class="dialog-body"><p class="form-note">以下内容未导入，其余地址不受影响。你可以复制浏览器地址栏中的网址后重新添加。</p>${result.rejected.slice(0,20).map(row=>`<div class="warning">第 ${row.row} 条：${esc(row.value)}<br>${esc(row.reason)}</div>`).join('')}</div><div class="dialog-footer"><button class="btn primary" data-action="close-modal">知道了</button></div>`,'import-result')}catch(err){$('#import-error').textContent=err.message}finally{el.disabled=false}return;
case 'save-rules':try{await api('rules',{rules:JSON.parse($('#rule-editor').value)});await load();toast('规则已保存；下一次分析将应用新规则')}catch(err){$('#rules-error').textContent=err.message}return;
case 'format-rules':try{$('#rule-editor').value=JSON.stringify(JSON.parse($('#rule-editor').value),null,2);$('#rules-error').textContent=''}catch(err){$('#rules-error').textContent='JSON 格式错误：'+err.message}return;
case 'about':return navigate('integrations');
}
}catch(err){toast(err.message)}});
document.addEventListener('input',e=>{if(e.target.id==='import-text'){selectedImportFile=null;$('#import-file-note').textContent='将导入下方粘贴的内容；无需填写供应商名称'}if(e.target.id==='search'){search=e.target.value;pageNo=1;$('#table-body').innerHTML=tableBody(page==='dashboard')}});
document.addEventListener('change',async e=>{if(e.target.id==='extra-filter'&&e.target.value){filter=e.target.value;pageNo=1;renderApp()}if(e.target.id==='import-file')await previewImportFile(e.target.files[0])});
for(const dialog of [$('#modal'),$('#drawer')])dialog.addEventListener('close',()=>{if(dialog.open)return;if(dialog.id==='drawer'){detailRequest++;drawerId=null}else contactEvidenceRequest++});
for(const dialog of [$('#modal'),$('#drawer')])dialog.addEventListener('click',e=>{if(e.target===dialog){const rect=dialog.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)dialog.close()}});
load();setInterval(async()=>{if(!state||refreshing)return;try{const newState=await api('state');const wasBusy=state.job.running,identityChanged=newState.username!==state.username;state=newState;if(identityChanged){detailRequest++;contactEvidenceRequest++;drawerId=null;if($('#modal').open)$('#modal').close();if($('#drawer').open)$('#drawer').close();if(typeof teamRequest!=='undefined'){teamRequest++;teamOverview=null;teamMember=null;teamBusy=false;teamError='';teamSelected=''}if(!state.is_admin&&page==='team')page='dashboard';renderApp();return}if(!$('#modal').open&&!$('#drawer').open&&!['search','rule-editor'].includes(document.activeElement?.id)){if(lastBusy||state.job.running)renderApp()}if(wasBusy&&!state.job.running)toast(state.job.status==='failed'?'模型服务失败，批次已停止；请检查 API 设置':state.job.status==='stopped'?'采集已停止，已完成结果保留':'批次处理完成，结果已保存')}catch{}},1500);
function discountText(value){return value==null?'未设置':Array.isArray(value)?value.map(v=>Number((v*10).toFixed(2))).join('–')+' 折':Number((value*10).toFixed(2))+' 折'}
function renderApp(){
 if(page==='team'&&state)return renderTeam();
 if(page==='contacts'&&state)return renderContacts();
 if(page==='rules'&&state){renderNav();$('#main').innerHTML=heading('报价规则','唯一采集范围：只查这里已保存的模型。新增需求直接添加；报价规则来自你提供的 A 部分。',`<button class="btn primary" data-action="add-rule">${I('plus')}新增模型需求</button>`,'YOUR SOURCING RULES')+`<div class="notice">${I('info')}参考折扣与询价门槛分别保存。GLM‑5.3 ≤4折；GLM‑5.2 / 5.1 按资源形态：自部署≤4折，官转≤5.5折。门槛已由用户确认，不再额外减1折。</div><section class="panel"><div class="panel-head"><div class="panel-title">A 部分 · 模型与询价门槛 <span class="chip">${state.rules.length} 项</span></div><span class="form-note">点击编辑即可修改，无需填写 JSON</span></div><div class="table-scroll"><table><thead><tr><th>模型匹配范围及别名</th><th>资源形态</th><th>当前参考折扣</th><th>可进入询价</th><th></th></tr></thead><tbody>${state.rules.map((r,i)=>`<tr><td><strong style="font-size:12px;color:#525a70">${esc(r.label||r.model)}</strong><small style="display:block;max-width:370px;white-space:normal;line-height:1.8;margin-top:8px;color:#9a9fb1">${esc((r.aliases||[r.model]).join(' / '))}${r.note?'<br>'+esc(r.note):''}</small></td><td>${esc((r.resource_forms||[]).join('、')||'未区分')}</td><td>${ruleReferenceText(r)}</td><td>${ruleThresholdText(r)}</td><td><button class="btn small" data-edit-rule="${i}">编辑</button></td></tr>`).join('')}</tbody></table></div></section>`;lastBusy=state.job.running;return}
 if(page==='integrations'&&state){renderNav();const m=state.model_service||{};$('#main').innerHTML=heading('模型服务与外部接入','每个账号的数据和模型配置独立保存；请使用自己的 API Key。','','CONNECTIONS')+`<div class="section-grid"><section class="panel"><div class="panel-head"><div class="panel-title">Agent 判断模型</div><span class="badge ${m.tested?'qualified':'pending'}">${m.tested?'连接测试通过':m.configured?'已配置，待测试':'待配置'}</span></div><div class="settings-content"><p class="form-note">支持兼容 Chat Completions 的模型接口。不绑定 Codex，也不会将“登录可用”当作服务已连接。</p><label class="field">API URL<input id="service-url" placeholder="https://你的模型服务地址/v1" value="${esc(m.base_url||'')}" autocomplete="off"></label><label class="field">调用模型名称<input id="service-model" placeholder="服务商提供的模型名称" value="${esc(m.model||'')}" autocomplete="off"><small>模型名称区分大小写；测试连接会自动核对服务商公布的同名模型。</small></label><label class="field">API Key<input id="service-key" type="password" placeholder="${m.key_configured?'已保存；留空保留原密钥':'填写 API Key'}" autocomplete="new-password"><small>${m.key_error?esc(m.key_error)+'。':''}${isCloud()?'密钥加密保存在当前账号下，仅供你发起的采集任务调用':(m.key_protected?'密钥经 Windows 凭据加密，仅当前 Windows 用户可解密':'密钥只保存在本机')}，不回显或导出；更换服务域名时请重新填写密钥。</small></label><div style="display:flex;gap:10px"><button class="btn primary" data-action="save-service">保存设置</button><button class="btn" data-action="test-service">测试连接</button></div><div class="form-error" id="service-error"></div><div class="form-note" id="service-note">${m.tested?'接口测试已通过；仍需在真实站点验证 Agent 工作流。':'填写此处 API URL、模型名称和密钥后，可在开始采集时选择全量或仅联系方式，由后台浏览器 Agent 运行。'}</div></div></section><section class="panel"><div class="panel-head"><div class="panel-title">浏览器与结果出口</div></div><div class="settings-content rule-explain"><p><strong>浏览器：Moli</strong><br>后台 Agent 读取页面后调用此处模型，逐步选择链接、公告、搜索和二维码；保留每步过程，可随时停止。</p><p><strong>报价规则：你提供的 A 部分</strong><br>新增模型、别名、资源形态和询价门槛，请到“报价规则”管理。</p><button class="btn small" data-nav="rules">管理模型需求 ${I('arrow')}</button><p><strong>飞书 / 邮箱</strong><br>当前仍支持表格导出和询价草稿；自动发送及同步未接通。</p><a class="btn small" href="/api/export?mode=${mode}">导出当前表格</a></div></section></div>`;lastBusy=state.job.running;return}
 return renderLegacyApp();
}
function openRule(index){const r=index==null?{}:state.rules[index];openModal(modalHead(index==null?'新增模型需求':'编辑报价规则','保存后成为采集目标；别名和资源形态会随规则一起提供给 Agent')+`<div class="dialog-body"><label class="field">模型名称<input id="rule-label" value="${esc(r.label||r.model||'')}" placeholder="例如：DeepSeek V4.1"></label><label class="field">匹配别名<textarea id="rule-aliases" rows="2">${esc((r.aliases||[]).join('，'))}</textarea><small>多个名称用逗号或换行分隔；请注明包含的版本、Flash、Pro 等。</small></label><label class="field">资源形态<input id="rule-forms" value="${esc((r.resource_forms||[]).join('，'))}" placeholder="例如：自部署，官转；不限制可留空"></label><label class="field">当前参考折扣<input id="rule-reference" value="${r.reference_discount==null?'':Array.isArray(r.reference_discount)?r.reference_discount.map(v=>v*10).join('-'):r.reference_discount*10}" placeholder="例如 4.5 或 4-5"></label><label class="field">本次可询价门槛（折）<input id="rule-threshold" type="number" min="0" max="10" step="0.1" value="${r.max_ratio==null?'':r.max_ratio*10}" placeholder="例如 4.5，表示 ≤4.5折；未确定可留空"></label><label class="field">按资源形态设置询价门槛（可选）<textarea id="rule-resource-gates" rows="2" placeholder="自部署=4&#10;官转=5.5">${esc(Object.entries(r.resource_thresholds||{}).map(([k,v])=>k+'='+(v*10)).join('\n'))}</textarea><small>填写后优先按形态判断；形态不明进入复核。</small></label><label class="field">按资源形态设置参考折扣（可选）<textarea id="rule-resource-refs" rows="2" placeholder="自部署=5&#10;官转=6.5">${esc(Object.entries(r.reference_by_resource||{}).map(([k,v])=>k+'='+(v*10)).join('\n'))}</textarea></label><label class="field">补充说明<textarea id="rule-note" rows="2">${esc(r.note||'')}</textarea></label><div class="form-error" id="rule-form-error"></div></div><div class="dialog-footer"><button class="btn" data-action="close-modal">取消</button><button class="btn primary" data-save-rule="${index==null?'new':index}">保存模型需求</button></div>`,'rule')}
document.addEventListener('click',async event=>{const el=event.target.closest('button');if(!el)return;if(el.dataset.editRule!==undefined)return openRule(Number(el.dataset.editRule));if(el.dataset.action==='add-rule')return openRule(null);if(el.dataset.saveRule!==undefined){try{const split=v=>v.split(/[,，\n]+/).map(s=>s.trim()).filter(Boolean);const label=$('#rule-label').value.trim();if(!label)throw Error('请填写模型名称');const old=el.dataset.saveRule==='new'?{}:state.rules[Number(el.dataset.saveRule)];const threshold=$('#rule-threshold').value.trim();const reference=$('#rule-reference').value.trim();const values=reference?reference.split(/[-–至]/).map(s=>Number(s.trim().replace(/折/g,''))/10):[];if(values.some(v=>!Number.isFinite(v)||v<0||v>1))throw Error('参考折扣请填 0–10 之间的数字或区间');const rule={...old,model:old.model||label.toLowerCase().replace(/\s+/g,'-'),label,aliases:split($('#rule-aliases').value),resource_forms:split($('#rule-forms').value),reference_discount:values.length>1?values:values[0]??null,min_ratio:0,max_ratio:threshold===''?null:Number(threshold)/10,review_margin:0,reference_input:old.reference_input??null,currency:old.currency||'USD',unit:old.unit||'1M tokens',note:$('#rule-note').value.trim(),source:old.source||'用户新增模型需求'};const parseMap=id=>Object.fromEntries($('#'+id).value.split(/[,，\n]+/).map(v=>v.trim()).filter(Boolean).map(line=>{const parts=line.split(/[=＝:：]/);if(parts.length!==2||!parts[0].trim()||!Number.isFinite(Number(parts[1]))||Number(parts[1])<=0||Number(parts[1])>10)throw Error('资源形态折扣请按 自部署=4 的形式填写');return [parts[0].trim(),Number(parts[1])/10]}));rule.resource_thresholds=parseMap('rule-resource-gates');rule.reference_by_resource=parseMap('rule-resource-refs');const rules=[...state.rules];if(el.dataset.saveRule==='new')rules.push(rule);else rules[Number(el.dataset.saveRule)]=rule;await api('rules',{rules});$('#modal').close();await load();toast('模型需求已保存；采集范围已更新')}catch(e){$('#rule-form-error').textContent=e.message}return}if(['save-service','test-service'].includes(el.dataset.action)){el.disabled=true;try{await api('model-service',{base_url:$('#service-url').value,model:$('#service-model').value,api_key:$('#service-key').value});if(el.dataset.action==='test-service'){const result=await api('model-service/test',{});toast('连接测试通过 · '+result.model+(result.model_adjusted?'（已匹配服务商准确名称）':''))}else toast('模型服务设置已保存；尚未测试连接');await load()}catch(e){$('#service-error').textContent=e.message}finally{el.disabled=false}}});

function ruleThresholdText(r){return r.resource_thresholds&&Object.keys(r.resource_thresholds).length?Object.entries(r.resource_thresholds).map(([name,value])=>esc(name)+' ≤'+discountText(value)).join(' / '):r.max_ratio==null?'门槛待补充':'≤ '+discountText(r.max_ratio)}
function ruleReferenceText(r){return r.reference_by_resource&&Object.keys(r.reference_by_resource).length?Object.entries(r.reference_by_resource).map(([name,value])=>esc(name)+' '+discountText(value)).join(' / '):discountText(r.reference_discount)}
const contactLabels={not_started:'待采集',legacy:'已有线索待核验',found:'已找到',needs_review:'待核实',incomplete:'尚未查清',blocked:'访问受阻'};
const contactTypes={email:'邮箱',phone:'电话',wechat:'微信',qq:'QQ',qq_group:'QQ群',wechat_link:'企业微信',official_account:'公众号',telegram:'Telegram',discord:'Discord',contact_form:'联系表单',online_service:'在线客服',qrcode:'二维码',other:'其他'};
function contactBadge(status){return `<span class="badge ${status==='found'?'qualified':status==='blocked'?'error':status==='not_started'?'pending':'review'}">${contactLabels[status]||'待采集'}</span>`}
function openRun(ids=null){const preferred=localStorage.getItem('scout-run-scope')||'contacts';openModal(modalHead('开始采集','配置模型 API 后，由模型观察页面并决定浏览器的下一步操作')+`<div class="dialog-body"><label class="field">本次采集内容<select id="run-scope"><option value="contacts" ${preferred==='contacts'?'selected':''}>仅采集联系方式</option><option value="all" ${preferred==='all'?'selected':''}>全量采集（报价＋联系方式）</option></select><small>仅联系方式：检查页面、公告、联系入口和二维码，保留已有报价及价格复核结果。全量：同时采集规则范围内模型的原始报价。</small></label><label class="field">处理范围<select id="run-selection" ${ids?'disabled':''}><option value="remaining">${ids?'仅当前供应商':'继续未完成的记录'}</option><option value="all">重新检查全部 ${rows().length} 家</option></select></label><div class="notice">${I('info')}${state.username?'发起账号：'+esc(state.username)+'。使用你自己的 API Key，配置将在开始时固定。':''}模型服务：${state.model_service?.configured?esc(state.model_service.model)+' · 已保存配置':'尚未配置 API URL、模型名和密钥'}。运行中可停止；模型服务出错会停止批次，不会把剩余网站都记为采集失败。</div>${mode==='demo'?'<div class="form-note">当前是示例工作区：只回放虚构数据，不调用真实模型或网站。切换真实采集可使用浏览器 Agent。</div>':''}<div class="form-error" id="run-error"></div></div><div class="dialog-footer"><button class="btn" data-nav="integrations">模型服务设置</button><button class="btn primary" data-action="confirm-run" data-ids="${ids?ids.join(','):''}">${I('play')}开始运行</button></div>`,'run')}
function renderContacts(){renderNav();const records=rows();const counts=records.reduce((all,row)=>(all[row.contact_status]=(all[row.contact_status]||0)+1,all),{});const selected=records.filter(row=>(filter==='all'||row.contact_status===filter||(filter.startsWith('todo_')&&matchesTask(row,filter)))&&(!search||(row.name+' '+row.url+' '+JSON.stringify(row.contacts)).toLowerCase().includes(search.toLowerCase())));const size=15;pageNo=Math.min(pageNo,Math.max(1,Math.ceil(selected.length/size)));const visible=selected.slice((pageNo-1)*size,pageNo*size);$('#main').innerHTML=heading('联系方式采集','只看联系线索和证据；报价与联系方式分开记录。',importButton()+runButton(),'CONTACT RESEARCH')+notice()+`<div class="metrics">${[['供应商',records.length,'users'],['已找到联系方式',counts.found||0,'check'],['待采集 / 待核验',(counts.not_started||0)+(counts.legacy||0),'clock'],['受阻 / 待继续',(counts.blocked||0)+(counts.incomplete||0)+(counts.needs_review||0),'review']].map(([label,value,icon])=>`<div class="metric"><div class="metric-heading">${label}<span class="metric-icon">${I(icon)}</span></div><div class="metric-value">${value}<small>家</small></div></div>`).join('')}</div>${pipeline()}<section class="panel"><div class="panel-head"><div class="panel-title">联系线索</div><a class="text-btn" href="/api/export-contacts?mode=${mode}">${I('download')}导出联系方式表</a></div><div class="table-tools"><div class="search">${I('search')}<input id="contact-search" placeholder="搜索编号、网址或联系方式" aria-label="搜索联系方式" value="${esc(search)}"></div><div class="filters">${taskFilters()}</div></div><div class="table-scroll"><table><thead><tr><th>编号 / 网站</th><th>处理阶段 / 下一步</th><th class="contact-col-head">联系方式</th><th>采集检查</th><th>最近检查</th><th></th></tr></thead><tbody>${visible.map(row=>{const fresh=row.contact_result?.contact_records||[];const flat=Object.entries(row.contacts).flatMap(([type,values])=>values.map(value=>({type,value})));return `<tr><td><button class="supplier-cell" data-detail="${row.id}"><span class="avatar c${row.id%5}">${esc(initials(row.name))}</span><span><strong>${esc(row.name)}</strong><small>${esc(new URL(row.url).hostname)}</small></span></button></td><td>${stageBadges(row)}</td><td>${contactColumn(row)}</td><td style="white-space:normal;max-width:200px;line-height:1.8">${contactBadge(row.contact_status)}<small class="contact-check-note">${esc(row.contact_result?.contact_summary||'尚未完成本轮检查')}</small></td><td>${time(row.contact_checked_at)}</td><td><button class="icon-btn" data-contact-evidence="${row.id}" title="查看联系证据">${I('arrow')}</button></td></tr>`}).join('')||'<tr><td colspan="6"><div class="empty">没有匹配的记录</div></td></tr>'}</tbody></table></div><div class="table-footer"><span>共 ${selected.length} 家 · 第 ${pageNo} 页</span><div class="pagination"><button data-action="prev" ${pageNo<=1?'disabled':''}>‹</button><button data-action="next" ${pageNo*size>=selected.length?'disabled':''}>›</button></div></div></section>`;lastBusy=state.job.running}
function contactEvidenceHTML(row){const result=row.contact_result||{};return `<section class="drawer-section"><h3>本轮联系方式检查 ${contactBadge(row.contact_status)}</h3><p>${esc(result.contact_summary||'本轮尚未完成；已有线索会保留')}</p><p>最近检查：${time(row.contact_checked_at)}</p>${(result.contact_records||[]).map(item=>`<div class="offer-card"><div class="offer-card-top"><strong>${esc(contactTypes[item.type]||item.type)}</strong><button class="icon-btn" data-copy="${esc(item.value)}" title="复制">${I('copy')}</button></div><p style="overflow-wrap:anywhere">${esc(item.value)}</p><p>用途：${esc(item.purpose||'待确认')}</p><div class="evidence">${esc(item.evidence)}</div>${item.qr_source_url?`<p>二维码解码原文 · <a href="${safeLink(item.qr_source_url)}" target="_blank" rel="noopener noreferrer">查看二维码来源</a></p>`:''}<a class="source-link" href="${safeLink(item.source_url)}" target="_blank" rel="noopener noreferrer">${esc(item.source_url)}</a>${(item.risk_flags||[]).length?`<div class="warning">${esc(item.risk_flags.join('；'))}</div>`:''}</div>`).join('')}${(result.previous_contact_records||[]).length?`<details><summary class="form-note" style="cursor:pointer">查看历史联系证据（本轮未必核验）</summary>${result.previous_contact_records.map(item=>`<div class="history-item"><strong>${esc(contactTypes[item.type]||item.type)} · ${esc(item.value)}</strong><p>${esc(item.purpose||'待确认')} · ${time(item.checked_at)}</p><div class="evidence">${esc(item.evidence)}</div><a href="${safeLink(item.source_url)}" target="_blank" rel="noopener noreferrer">${esc(item.source_url)}</a><p>${esc((item.risk_flags||[]).join('；'))}</p></div>`).join('')}</details>`:''}${(result.steps||[]).length?`<details><summary class="form-note" style="cursor:pointer">查看 Agent 的 ${result.steps.length} 步检查过程</summary>${result.steps.map(step=>`<div class="history-item">${esc(step.action||'观察')} · ${esc(step.reason||'')}<br>${esc(step.url||'')}</div>`).join('')}</details>`:''}${(result.warnings||[]).map(message=>`<div class="warning">${esc(message)}</div>`).join('')}<button class="btn small" data-agent-retry="${row.id}">${I('refresh')}选择模式重新采集</button></section>`}
document.addEventListener('click',async event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.agentRetry)return openRun([Number(button.dataset.agentRetry)]);if(button.dataset.action==='confirm-run'){button.disabled=true;try{const scope=$('#run-scope').value;localStorage.setItem('scout-run-scope',scope);const ids=button.dataset.ids?button.dataset.ids.split(',').map(Number):null;await api('run',{mode,scope,selection:$('#run-selection').value,ids});$('#modal').close();page='contacts';filter='all';search='';pageNo=1;await load();toast(mode==='demo'?'开始示例回放':'浏览器 Agent 已开始运行')}catch(error){$('#run-error').textContent=error.message}finally{button.disabled=false}}});
document.addEventListener('input',event=>{if(event.target.id==='contact-search'){const value=event.target.value,position=event.target.selectionStart;search=value;pageNo=1;renderContacts();const input=$('#contact-search');input.focus();input.setSelectionRange(position,position)}});

function contactEntries(row){
 const current=row.contact_result?.contact_records||[],history=row.contact_result?.previous_contact_records||[];
 return Object.entries(row.contacts||{}).flatMap(([type,values])=>values.map(value=>{const verified=current.find(r=>r.type===type&&r.value===value);return {type,value,...(verified||history.find(r=>r.type===type&&r.value===value)||{}),verified_this_run:Boolean(verified)}}));
}
function followupStages(row){
 const entries=contactEntries(row),mail=entries.some(item=>item.type==='email'&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(item.value));
 const manual=entries.some(item=>['phone','wechat','qq','qq_group','wechat_link','official_account','telegram','discord','contact_form','online_service'].includes(item.type));
 const stages=[];
 const manualDecision=String(row.reason||'').startsWith('人工复核：');
 if(manualDecision&&row.status==='skipped')return [{key:'price_skip',label:'已人工跳过 · 暂不跟进',tone:'skipped'}];
 if(manualDecision&&row.status==='qualified')stages.push({key:'price_ready',label:'报价已人工通过',tone:'qualified'});
 else if(row.needs_price_review??row.offers.some(offer=>offer.status==='review'||!Number.isFinite(offer.ratio)))stages.push({key:'todo_price',label:'模型折扣待复核',tone:'review'});
 else if(row.status==='qualified')stages.push({key:'price_ready',label:'报价符合询价条件',tone:'qualified'});
 else if(row.status==='skipped')stages.push({key:'price_skip',label:'报价暂不跟进',tone:'skipped'});
 else stages.push({key:'price_missing',label:'报价待采集',tone:'pending'});
 if(mail)stages.push({key:'todo_email',label:'可邮件联系',tone:'qualified'});
 if(manual)stages.push({key:'todo_manual',label:'已找到联系方式 · 待人工联系',tone:'pending'});
 if(!mail&&!manual)stages.push({key:'todo_contact',label:entries.length?'联系方式待核验':row.contact_status==='blocked'?'联系方式采集受阻':'联系方式待补查',tone:row.contact_status==='blocked'?'error':'review'});
 return stages;
}
function isManualTask(row){return !(String(row.reason||'').startsWith('人工复核：')&&row.status==='skipped')&&(row.status==='review'||row.status==='error'||['blocked','incomplete','needs_review'].includes(row.contact_status)||followupStages(row).some(stage=>['todo_manual','todo_email'].includes(stage.key)))}
function stageBadges(row,priceOnly=false){return `<div class="stage-badges">${followupStages(row).filter(stage=>!priceOnly||stage.key==='todo_price'||stage.key.startsWith('price_')).map(stage=>`<span class="badge ${stage.tone}" data-stage="${stage.key}">${stage.label}</span>`).join('')}</div>`}
function matchesTask(row,value){return followupStages(row).some(stage=>stage.key===value)}
function taskFilters(){return [['all','全部'],['todo_manual','待人工联系'],['todo_price','折扣待复核'],['todo_email','可邮件联系'],['todo_contact','联系方式待补查']].map(([key,label])=>`<button data-filter="${key}" class="filter ${filter===key?'active':''}">${label}</button>`).join('')}
function contactDisplay(item){
 const value=String(item.value),url=/^https?:\/\//i.test(value);
 if(!url)return esc(value);
 if(item.type==='wechat_link')return '打开企业微信添加链接';
 if(item.type==='qrcode')return '查看联系二维码';
 if(item.type==='qq_group')return '打开加群链接';
 if(item.type==='telegram')return esc(value.replace(/^https?:\/\/(?:t\.me|telegram\.me)\//i,'@'));
 if(item.type==='discord')return '打开 Discord 邀请';
 try{return esc(new URL(value).hostname+new URL(value).pathname)}catch{return esc(value)}
}
function contactColumn(row){
 const entries=contactEntries(row);
 const itemHTML=item=>`<div class="inline-contact"><span class="contact-kind">${esc(contactTypes[item.type]||item.type)}</span><div class="inline-contact-value">${/^https?:\/\//i.test(item.value)?`<a href="${safeLink(item.value)}" title="${esc(item.value)}" target="_blank" rel="noopener noreferrer">${contactDisplay(item)} ${I('external')}</a>`:`<span>${contactDisplay(item)}</span>`}${item.purpose?`<small title="${esc(item.purpose)}">${esc(item.purpose)}</small>`:''}${(item.risk_flags||[]).some(flag=>/历史|失效/.test(flag))?'<small class="contact-risk">历史线索 · 有效性待确认</small>':!item.verified_this_run?'<small class="contact-risk">已有线索 · 待本轮核验</small>':''}</div><button class="icon-btn" data-copy="${esc(item.value)}" title="复制${esc(contactTypes[item.type]||item.type)}">${I('copy')}</button></div>`;
 return `<div class="contact-column">${entries.length?entries.slice(0,3).map(itemHTML).join(''):`<span class="contact-empty">${row.contact_status==='blocked'?'采集受阻，需继续查找':'尚无已核实的联系线索'}</span>`}${entries.length>3?`<details class="more-contacts"><summary>另 ${entries.length-3} 个联系渠道</summary>${entries.slice(3).map(itemHTML).join('')}</details>`:''}<div class="contact-row-actions">${entries.some(item=>item.type==='email')?`<button class="text-btn" data-draft="${row.id}">${I('mail')}写询价邮件</button>`:''}<button class="text-btn" data-contact-evidence="${row.id}">来源与过程 ${I('chevron')}</button></div></div>`;
}
function quoteNumber(value){return typeof value==='number'?value.toLocaleString('en-US',{maximumFractionDigits:8}):'待确认'}
function quoteSummary(row){
 const offer=row.offers.find(item=>Number.isFinite(item.ratio))||row.offers[0];
 if(!offer)return '<span class="contact-empty">尚无报价</span>';
 return `<div class="quote-summary">${Number.isFinite(offer.ratio)?`<strong>${Number((offer.ratio*10).toFixed(2))}<small>折</small></strong>`:offer.input_price!=null?`<small>输入单价</small><strong>${quoteNumber(offer.input_price)} <small>${esc(offer.currency||'币种待确认')}</small></strong><small>每 ${esc(offer.unit||'计价单位待确认')}</small>`:'<span>价格条件待核对</span>'}<button class="text-btn" data-detail="${row.id}">查看 ${offerCount(row)} 条报价 ${I('chevron')}</button></div>`;
}
function quoteCard(offer){
 const known=Number.isFinite(offer.ratio),currency=offer.currency==='CNY'?'¥':offer.currency==='USD'?'$':offer.currency?offer.currency+' ':'';
 return `<article class="price-card"><div class="price-card-head"><strong>${esc(offer.model_name||modelName(offer.model))}</strong><span class="badge ${known?(offer.status==='qualified'?'qualified':offer.status==='skipped'?'skipped':'review'):'review'}">${known?Number((offer.ratio*10).toFixed(2))+' 折'+(offer.status==='skipped'?' · 暂不跟进':offer.status==='review'?' · 待复核':''):'折扣待复核'}</span></div><div class="price-card-unit">${esc(offer.currency||'币种待确认')} · 每 ${esc(offer.unit||'计价单位待确认')}</div>${offer.input_price!=null||offer.output_price!=null?`<div class="price-values">${[['输入',offer.input_price],['输出',offer.output_price],['缓存读取',offer.cache_price]].map(([label,value])=>`<div><span>${label}</span><strong>${value==null?'—':esc(currency)+quoteNumber(value)}</strong></div>`).join('')}</div>`:known?`<div class="price-discount">${Number((offer.ratio*10).toFixed(2))}<small>折</small></div>`:'<p>尚未取得可比较的单价</p>'}<div class="price-card-meta"><span>分组 <b>${esc(offer.group||'未说明')}</b></span>${offer.group_multiplier!=null?`<span>分组倍率 <b>×${esc(offer.group_multiplier)}</b></span>`:''}<span>资源 <b>${esc(offer.resource_form||'待确认')}</b></span></div><details class="price-evidence"><summary>条件、判断与来源 ${I('chevron')}</summary>${offer.price_text?`<p>${esc(offer.price_text)}</p>`:''}${offer.notes?`<p>${esc(offer.notes)}</p>`:''}<p>${esc(offer.reason||'')}</p><div class="evidence">${esc(offer.evidence||'暂无原文证据')}</div>${offer.source?`<a class="source-link" href="${safeLink(offer.source)}" target="_blank" rel="noopener noreferrer">打开原始报价页 ${I('external')}</a>`:''}</details></article>`;
}
function quoteCards(row){
 if(row._summary)return '<p role="status">正在加载完整报价…</p>';
 const groups=new Map();for(const offer of row.offers){const key=modelName(offer.model);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(offer)}
 return `<div class="quote-view-note">先看单价与分组；原文、限制条件和计算依据可展开查看。分组倍率与官方目录价折扣分别记录。</div>${[...groups].map(([name,offers],index)=>`<details class="quote-family" ${index===0?'open':''}><summary><strong>${esc(name)}</strong><span>${offers.length} 条报价 ${I('chevron')}</span></summary><div class="price-card-grid">${offers.map(quoteCard).join('')}</div></details>`).join('')||'<p>尚未取得目标模型报价。可重新选择全量采集，或打开供应商网页核对。</p>'}`;
}
async function openContactEvidence(id){
 const request=++contactEvidenceRequest;
 const preview=state.suppliers.find(item=>item.id===id);if(!preview)return;
 if(preview._summary)openModal(modalHead('联系来源与检查过程',esc(preview.name))+'<div class="dialog-body" role="status">正在加载完整证据与检查过程…</div>','contact-evidence');
 try{const row=await supplierDetail(id);if(request!==contactEvidenceRequest)return;openModal(modalHead('联系来源与检查过程',row.name+' · '+new URL(row.url).hostname)+`<div class="dialog-body"><p class="form-note">联系方式已直接显示在表格对应栏。这里用于核对证据、用途和历史线索。</p>${contactEvidenceHTML(row)}</div>`,'contact-evidence');}catch(error){if(request!==contactEvidenceRequest)return;openModal(modalHead('联系证据加载失败')+`<div class="dialog-body">${esc(error.message)}<p>关闭后重新打开可重试。</p></div>`,'contact-evidence')}
}
document.addEventListener('click',event=>{const button=event.target.closest('button');if(button?.dataset.contactEvidence)openContactEvidence(Number(button.dataset.contactEvidence))});
